import json
d=json.load(open('bench/results/2026-10-12/m1-ngram/recon/event_samples.json'))
s=d['samples']
for k,v in s.items():
    print('===', k, '===')
    e=v['event']
    # truncate long strings
    def shr(x, n=300):
        if isinstance(x, str): return repr(x[:n])
        return repr(x)[:n]
    def walk(obj, depth=0, pref=''):
        if isinstance(obj, dict):
            for kk,vv in obj.items():
                print(pref+str(kk), ':', shr(vv) if depth<4 else (str(vv)[:60]))
        # print compactly
    # just compact json, truncated
    print(json.dumps(e, default=str)[:2000])
    print()
" 2>&1 | head -120

